#!/bin/sh
# Type-checks the Android sources (launcher hooks, entry point, settings UI) against hand-written
# android / launcher3 / Xposed API stubs. Catches syntax errors, wrong signatures and missing
# imports without needing the Android SDK. CI uses the real SDK via ./gradlew.
set -e
cd "$(dirname "$0")"
OUT=build/android-check
rm -rf "$OUT"
mkdir -p "$OUT/src" "$OUT/classes"
python3 tools/verify_android_stubs.py "$OUT/src" >/dev/null

# R is generated by aapt2 from res/; mirror the string ids from strings.xml
mkdir -p "$OUT/src/com/plallappsshape"
{
  echo 'package com.plallappsshape;'
  echo 'public final class R {'
  echo '    public static final class string {'
  i=1
  for name in $(sed -n 's/.*name="\([^"]*\)".*/\1/p' app/src/main/res/values/strings.xml); do
    echo "        public static final int $name = 0x7f01000$i;"
    i=$((i+1))
  done
  echo '    }'
  echo '}'
} > "$OUT/src/com/plallappsshape/R.java"

cp -r app/src/main/java/com/plallappsshape/launcher app/src/main/java/com/plallappsshape/settings \
    "$OUT/src/com/plallappsshape/"

JAVAC=${JAVAC:-javac}
$JAVAC -Xlint:-options -source 11 -target 11 -nowarn -d "$OUT/classes" \
    $(find "$OUT/src" -name '*.java')
echo "android source check: OK ($(find "$OUT/classes" -name '*.class' | wc -l) classes)"
